function D.on(signal, fn)
	local c = signal:Connect(fn)
	D.conns[#D.conns + 1] = c
	return c
end

function D.onCleanup(fn)
	D.cleanups[#D.cleanups + 1] = fn
end

function D.safe(fn, ...)
	return pcall(fn, ...)
end

function D.ensureDir(path)
	pcall(function()
		if makefolder and isfolder and not isfolder(path) then makefolder(path) end
	end)
end
